1],[38.755048,-0.056534],[38.754984,-0.056512],[38.754984,-0.056512],[38.754948,-0.056507],[38.754898,-0.056497],[38.754858,-0.056481],[38.754814,-0.056491],[38.754767,-0.056508],[38.754713,-0.056529],[38.754661,-0.056558],[38.754623,-0.056576],[38.75456,-0.056603],[38.754503,-0.056609],[38.754428,-0.056615],[38.754362,-0.056593],[38.754307,-0.056567],[38.754262,-0.056519],[38.75421,-0.056442],[38.754162,-0.056401],[38.754128,-0.056381],[38.754081,-0.056392],[38.754012,-0.056406],[38.753968,-0.056423],[38.753903,-0.056443],[38.753836,-0.056445],[38.753765,-0.056433],[38.753698,-0.056417],[38.753644,-0.056396],[38.753589,-0.056388],[38.75354,-0.056379],[38.753465,-0.056373],[38.753411,-0.056364],[38.753356,-0.05637],[38.753303,-0.056368],[38.753249,-0.056357],[38.753222,-0.056357],[38.75319,-0.056337],[38.753162,-0.056294],[38.753106,-0.056191],[38.753081,-0.056117],[38.753063,-0.056055],[38.753049,-0.056001],[38.753034,-0.055958],[38.753011,-0.055892],[38.752981,-0.055835],[38.752945,-0.055685],[38.752935,-0.055617],[38.75293,-0.055555],[38.752926,-0.055444],[38.75292,-0.055389],[38.752911,-0.055325],[38.752917,-0.055277],[38.752917,-0.055236],[38.752914,-0.055183],[38.752908,-0.055151],[38.752896,-0.055114],[38.75288,-0.055123],[38.752859,-0.055121],[38.752836,-0.055137],[38.752806,-0.055146],[38.752763,-0.055177],[38.75271,-0.0552],[38.752667,-0.055188],[38.7526,-0.055191],[38.752541,-0.055179],[38.752492,-0.055176],[38.752435,-0.055176],[38.752384,-0.055178],[38.752337,-0.05518],[38.752277,-0.055191],[38.752237,-0.055202],[38.752191,-0.055214],[38.752127,-0.055215],[38.75209,-0.055216],[38.752046,-0.055213],[38.751992,-0.055196],[38.75193,-0.055169],[38.75186,-0.055136],[38.751773,-0.055096],[38.751648,-0.055056],[38.751553,-0.055021],[38.751496,-0.055006],[38.751422,-0.054979],[38.751366,-0.054969],[38.751302,-0.054969],[38.751241,-0.054971],[38.751185,-0.054982],[38.751111,-0.054999],[38.751041,-0.055017],[38.750993,-0.055022],[38.750935,-0.055025],[38.750876,-0.055021],[38.750848,-0.055022],[38.750805,-0.05504],[38.750755,-0.05506],[38.75071,-0.055082],[38.750647,-0.055121],[38.750585,-0.055163],[38.750539,-0.055191],[38.750485,-0.055218],[38.750411,-0.055245],[38.75035,-0.055271],[38.750289,-0.055296],[38.75024,-0.055317],[38.750191,-0.055333],[38.750121,-0.055362],[38.750052,-0.055388],[38.749993,-0.055428],[38.749958,-0.055478],[38.749899,-0.055544],[38.749845,-0.055621],[38.749807,-0.055671],[38.74977,-0.055731],[38.749708,-0.055817],[38.74967,-0.055869],[38.749634,-0.055912],[38.749582,-0.055969],[38.749547,-0.056018],[38.749509,-0.056063],[38.749461,-0.056111],[38.749408,-0.056164],[38.749371,-0.056198],[38.74931,-0.056258],[38.749268,-0.056287],[38.749227,-0.056307],[38.749176,-0.056342],[38.749126,-0.05636],[38.74912,-0.056368]]}]'::jsonb;
  v_source jsonb;
  v_route record;
  v_points jsonb;
  v_segments jsonb;
  v_count integer;
  v_length_km double precision;
  v_max_gap_km double precision;
  v_center_gap_km double precision;
  v_invalid integer;
  v_id text;
  v_slug text;
  v_official_km double precision;
begin
  for v_source in select value from jsonb_array_elements(v_sources) as x(value) loop
    v_id := v_source->>'route_id';
    v_slug := v_source->>'slug';
    v_official_km := (v_source->>'official_km')::double precision;
    select h.id,h.route_ref,h.distance_km,h.latitude,h.longitude,t.status
      into v_route from public.hiking_routes h
      left join public.hiking_route_tracks t on t.route_id=h.id
      where h.id=v_id and h.source='openstreetmap'
        and h.official_url like '%femecv.com/%'
        and regexp_replace(h.official_url,'^.*/','')=v_slug
        and regexp_replace(lower(h.route_ref),'[^a-z0-9]+','','g')
          =replace(v_slug,'-','')
        and exists (select 1 from public.hiking_route_regions m
          where m.route_id=h.id and m.published);
    if not found or v_route.status='ready' then continue; end if;
    with points as (
      select ordinality as idx,(point->>0)::double precision lat,
        (point->>1)::double precision lon
      from jsonb_array_elements(v_source->'coords')
        with ordinality as p(point,ordinality)
    ), steps as (
      select lat,lon,lag(lat) over(order by idx) prev_lat,
        lag(lon) over(order by idx) prev_lon from points
    ), distances as (
      select case when prev_lat is null then 0 else 6371*2*asin(sqrt(
        least(1,power(sin(radians(lat-prev_lat)/2),2)+
        cos(radians(prev_lat))*cos(radians(lat))*
        power(sin(radians(lon-prev_lon)/2),2)))) end step_km,
        6371*2*asin(sqrt(least(1,
          power(sin(radians(lat-v_route.latitude)/2),2)+
          cos(radians(v_route.latitude))*cos(radians(lat))*
          power(sin(radians(lon-v_route.longitude)/2),2)))) center_km,
        (lat between 27 and 45 and lon between -19 and 5) valid from steps
    )
    select count(*),coalesce(sum(step_km),0),coalesce(max(step_km),0),
      coalesce(min(center_km),999),count(*) filter(where not valid)
      into v_count,v_length_km,v_max_gap_km,v_center_gap_km,v_invalid
      from distances;
    if v_count<>(v_source->>'expected_points')::integer or v_count<100
      or v_invalid>0 or v_length_km<=0 or v_max_gap_km>0.35
      or v_center_gap_km>1
      or abs(v_length_km/v_official_km-1)>0.10
      or (v_route.distance_km is not null
        and abs(v_length_km/v_route.distance_km-1)>0.12) then
      raise exception 'FEMECV track validation failed for %: %, %, %, %, %',
        v_id,v_count,v_length_km,v_max_gap_km,v_center_gap_km,v_invalid;
    end if;
    select jsonb_agg(jsonb_build_object('lat',(point->>0)::double precision,
      'lon',(point->>1)::double precision) order by ordinality)
      into v_points from jsonb_array_elements(v_source->'coords')
        with ordinality as p(point,ordinality);
    v_segments := jsonb_build_array(v_points);
    insert into public.hiking_route_tracks
      (route_id,status,segments,checked_at,continuity_checked,
       geometry_source,geometry_source_url,official)
    values (v_id,'ready',v_segments,now(),true,
      'Federación de Deportes de Montaña y Escalada de la Comunitat Valenciana (FEMECV)',
      v_source->>'gpx_url',true)
    on conflict(route_id) do update set
      status=excluded.status,segments=excluded.segments,
      checked_at=excluded.checked_at,continuity_checked=true,
      geometry_source=excluded.geometry_source,
      geometry_source_url=excluded.geometry_source_url,official=true;
    update public.hiking_routes set trace_available=true,published=true,
      distance_km=coalesce(distance_km,v_official_km)
      where id=v_id;
  end loop;
end
$curate$;
